$(function(){var n=$("#profile-image");n.click(function(){var t=$(document).width(),i=$(document).height(),r=75+Math.random()*(t-150),u=75+Math.random()*(i-150);n.css({top:u+"px",right:r+"px",position:"fixed"});gtag("event","profile_click",{event_category:"Profile Image Click"})});$(".main-menu-button").click(function(){gtag("event","link",{event_category:"Main Button",href:$(this).attr("href")});$(this).remove()});$(".main-menu-text").click(function(){gtag("event","text",{event_category:"Main Text Hidden",value:$(this).text()});$(this).remove()})});